   "message": "string"
  }
 }
}

{
 "app_name": "venmo",
 "api_name": "add_to_venmo_balance",
 "path": "/balance",
 "method": "POST",
 "description": "Add money to your Venmo balance.",
 "parameters": [
  {
   "name": "amount",
   "type": "number",
   "required": true,
   "description": "Amount to add to Venmo balance.",
   "default": null,
   "constraints": [
    "value > 0.0"
   ]
  },
  {
   "name": "payment_card_id",
   "type": "integer",
   "required": true,
   "description": "ID of the payment card to use for adding balance.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string",
   "bank_transfer_id": 1
  },
  "failure": {
   "message": "string"
  }
 }
}
{
 "app_name": "venmo",
 "api_name": "show_bank_transfer_history",
 "path": "/bank_transfers",
 "method": "GET",
 "description": "Show histroy of money transfer from Venmo to payment card and vice versa.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "transfer_type",
   "type": "string",
   "required": false,
   "description": "Filter bank transfers by type. Will skip filtering if not passed.",
   "default": null,
   "constraints": [
    "value in ['card_to_venmo', 'venmo_to_card']"
   ]
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1.0, <= 20.0"
   ]
  }
 ],
 "response_schemas": {
  "success": [
   {
    "bank_transfer_id": 1,
    "transfer_type": "card_to_venmo",
    "amount": 0.0,
    "payment_card_digits": "string",
    "created_at": "2019-01-01T00:00:00"
   }
  ],
  "failure": {
   "message": "string"
  }
 }
